describe("표시 규칙(기존 규칙을 정확값에 적용) — 경계", () => {
  it("formatKRW·formatUnit 경계와 동률", () => {
    expect(fmtKRW(q(BigInt("2499999999"), BigInt("25")))).toBe("100,000,000원");
    expect(fmtUnit(q(BigInt("2499999999"), BigInt("25")))).toBe("10000만");
    expect(fmtKRW(q(BigInt("100000000"), BigInt("1")))).toBe("100,000,000원");
    expect(fmtUnit(q(BigInt("100000000"), BigInt("1")))).toBe("1억");
    expect(fmtKRW(q(BigInt("99999999999999999999999999999999999999"), BigInt("1000000000000000000000000000000")))).toBe("100,000,000원");
    expect(fmtUnit(q(BigInt("99999999999999999999999999999999999999"), BigInt("1000000000000000000000000000000")))).toBe("10000만");
    expect(fmtKRW(q(BigInt("105000000"), BigInt("1")))).toBe("105,000,000원");
    expect(fmtUnit(q(BigInt("105000000"), BigInt("1")))).toBe("1.1억");
    expect(fmtKRW(q(BigInt("104999999"), BigInt("1")))).toBe("104,999,999원");
    expect(fmtUnit(q(BigInt("104999999"), BigInt("1")))).toBe("1억");
    expect(fmtKRW(q(BigInt("150000000"), BigInt("1")))).toBe("150,000,000원");
    expect(fmtUnit(q(BigInt("150000000"), BigInt("1")))).toBe("1.5억");
    expect(fmtKRW(q(BigInt("1000000000"), BigInt("1")))).toBe("1,000,000,000원");
    expect(fmtUnit(q(BigInt("1000000000"), BigInt("1")))).toBe("10억");
    expect(fmtKRW(q(BigInt("19999"), BigInt("2")))).toBe("10,000원");
    expect(fmtUnit(q(BigInt("19999"), BigInt("2")))).toBe("10,000원");
    expect(fmtKRW(q(BigInt("1"), BigInt("2")))).toBe("1원");
    expect(fmtUnit(q(BigInt("1"), BigInt("2")))).toBe("1원");
    expect(fmtKRW(q(BigInt("-2"), BigInt("5")))).toBe("-0원");
    expect(fmtUnit(q(BigInt("-2"), BigInt("5")))).toBe("-0원");
    expect(fmtKRW(q(BigInt("-1"), BigInt("2")))).toBe("-0원");
    expect(fmtUnit(q(BigInt("-1"), BigInt("2")))).toBe("-0원");
    expect(fmtKRW(q(BigInt("-3"), BigInt("2")))).toBe("-1원");
    expect(fmtUnit(q(BigInt("-3"), BigInt("2")))).toBe("-1원");
    expect(fmtKRW(q(BigInt("24691357"), BigInt("2")))).toBe("12,345,679원");
    expect(fmtUnit(q(BigInt("24691357"), BigInt("2")))).toBe("1235만");
    expect(fmtKRW(q(BigInt("19999"), BigInt("2")))).toBe("10,000원");
    expect(fmtUnit(q(BigInt("19999"), BigInt("2")))).toBe("10,000원");
    expect(fmtKRW(q(BigInt("10000"), BigInt("1")))).toBe("10,000원");
    expect(fmtUnit(q(BigInt("10000"), BigInt("1")))).toBe("1만");
    expect(fmtKRW(q(BigInt("-105000000"), BigInt("1")))).toBe("-105,000,000원");
    expect(fmtUnit(q(BigInt("-105000000"), BigInt("1")))).toBe("-1.1억");
  });
  it("toFixed(2) — 동률은 큰 쪽, 10^21 이상도 지수 표기 없이", () => {
    expect(fmtFixed(q(BigInt("201"), BigInt("200")), 2)).toBe("1.01");
    expect(fmtFixed(q(BigInt("-201"), BigInt("200")), 2)).toBe("-1.01");
    expect(fmtFixed(q(BigInt("2000000000000000000000000001"), BigInt("200")), 2)).toBe("10000000000000000000000000.01");
    expect(fmtFixed(q(BigInt("1"), BigInt("1000")), 2)).toBe("0.00");
    expect(fmtFixed(q(BigInt("1"), BigInt("500")), 2)).toBe("0.00");
  });
});

describe("지원 상한 2^1024원 — 정확한 경계는 지원 밖(미만만 계산)", () => {
  it("구간·정확값 판정", () => {
    expect(AMOUNT_LIMIT).toBe(BigInt(2) ** BigInt(1024));
    const S = 64, sh = BigInt(S);
    const at = { lo: AMOUNT_LIMIT << sh, hi: AMOUNT_LIMIT << sh };
    const below = { lo: (AMOUNT_LIMIT << sh) - BigInt(1), hi: (AMOUNT_LIMIT << sh) - BigInt(1) };
    const R = new Resolver(S, 8);
    expect(R.below(at, AMOUNT_LIMIT, () => q(AMOUNT_LIMIT))).toBe(false);
    expect(R.below(below, AMOUNT_LIMIT, () => q((AMOUNT_LIMIT << sh) - BigInt(1), BigInt(1) << sh))).toBe(true);
    // 구간이 경계를 품으면 정확값으로 판정
    const straddle = { lo: (AMOUNT_LIMIT << sh) - BigInt(1), hi: (AMOUNT_LIMIT << sh) + BigInt(1) };
    expect(R.below(straddle, AMOUNT_LIMIT, () => q(AMOUNT_LIMIT))).toBe(false);
    expect(R.below(straddle, AMOUNT_LIMIT, () => q(AMOUNT_LIMIT - BigInt(1)))).toBe(true);
  });
});

describe("입력칸 표시 — 2^53을 넘는 숫자도 자릿수 유지(타이핑 중 raw가 바뀌지 않게)", () => {
  it("money·integer·decimal 정수부", () => {
    expect(toDisplay("9007199254740991", "money")).toBe("9,007,199,254,740,991");
    expect(toDisplay("9007199254740993", "money")).toBe("9,007,199,254,740,993");
    expect(toDisplay("12345678901234567", "money")).toBe("12,345,678,901,234,567");
    expect(toDisplay("12345678901234567890", "money")).toBe("12,345,678,901,234,567,890");
    expect(toDisplay("9999999999999999999999999999999999999999", "integer")).toBe("9,999,999,999,999,999,999,999,999,999,999,999,999,999");
    expect(toDisplay("", "money")).toBe("10,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000,000");
    expect(toDisplay("12345678901234567890.5", "decimal")).toBe("12,345,678,901,234,567,890.5");
    expect(toDisplay("12345678901234567890.", "decimal")).toBe("12,345,678,901,234,567,890.");
    expect(toDisplay("12345678901234567890.50", "decimal")).toBe("12,345,678,901,234,567,890.50");
    expect(toDisplay("1234567", "money")).toBe("1,234,567");
    expect(toDisplay("007", "money")).toBe("7");
    expect(toDisplay("1234.5", "decimal")).toBe("1,234.5");
  });
});
